{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "food_drink_section",
        "checklist_section",
        "quick_actions_section"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Central Park Birthday Picnic Plan: July 20th Celebration",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Plan a delightful outdoor birthday picnic for 15 guests in Central Park, New York City, on July 20, 2024. This plan focuses on easy-to-prepare, budget-friendly food and essential items to ensure a smooth and enjoyable celebration."
      },
      "children": []
    },
    "food_drink_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "food_drink_header",
        "food_drink_description",
        "main_dishes_stack",
        "snacks_dessert_stack",
        "drinks_stack"
      ]
    },
    "food_drink_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "food_icon",
        "food_drink_title"
      ]
    },
    "food_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg"
      },
      "children": []
    },
    "food_drink_title": {
      "type": "Text",
      "props": {
        "text": "Food & Drink Suggestions ($200 Budget)",
        "variant": "h2"
      },
      "children": []
    },
    "food_drink_description": {
      "type": "Text",
      "props": {
        "text": "Keeping the $200 budget for 15 people in mind, focus on homemade or cost-effective bulk items that are easy to transport and serve."
      },
      "children": []
    },
    "main_dishes_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "main_dishes_title",
        "main_dishes_item_1",
        "main_dishes_item_2",
        "main_dishes_item_3",
        "main_dishes_item_4"
      ]
    },
    "main_dishes_title": {
      "type": "Text",
      "props": {
        "text": "Main Dishes & Sides:",
        "variant": "h3"
      },
      "children": []
    },
    "main_dishes_item_1": {
      "type": "Text",
      "props": {
        "text": "Assorted Sandwiches/Wraps: Prepare a variety of turkey & cheese, ham & swiss, and vegetarian (cucumber, cream cheese, lettuce) sandwiches or wraps on whole wheat bread/tortillas. Cut into halves for easy serving."
      },
      "children": []
    },
    "main_dishes_item_2": {
      "type": "Text",
      "props": {
        "text": "Pasta Salad: A large batch of cold pasta salad with cherry tomatoes, cucumber, bell peppers, olives, and a light vinaigrette dressing."
      },
      "children": []
    },
    "main_dishes_item_3": {
      "type": "Text",
      "props": {
        "text": "Quinoa Salad: A hearty quinoa salad with chickpeas, corn, black beans, and a lime-cilantro dressing."
      },
      "children": []
    },
    "main_dishes_item_4": {
      "type": "Text",
      "props": {
        "text": "Veggie Sticks & Dip: Carrot sticks, celery sticks, and bell pepper strips with a large tub of hummus or ranch dip."
      },
      "children": []
    },
    "snacks_dessert_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "snacks_dessert_title",
        "snacks_dessert_item_1",
        "snacks_dessert_item_2",
        "snacks_dessert_item_3"
      ]
    },
    "snacks_dessert_title": {
      "type": "Text",
      "props": {
        "text": "Snacks & Dessert:",
        "variant": "h3"
      },
      "children": []
    },
    "snacks_dessert_item_1": {
      "type": "Text",
      "props": {
        "text": "Fruit Platter: A mix of pre-cut watermelon, cantaloupe, grapes, and berries."
      },
      "children": []
    },
    "snacks_dessert_item_2": {
      "type": "Text",
      "props": {
        "text": "Chips/Pretzels: Large bags of assorted chips and pretzels."
      },
      "children": []
    },
    "snacks_dessert_item_3": {
      "type": "Text",
      "props": {
        "text": "Homemade Brownies/Cookies: Bake a batch of brownies or cookies, or purchase an economical tray from a local bakery or grocery store."
      },
      "children": []
    },
    "drinks_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "drinks_title",
        "drinks_item_1",
        "drinks_item_2",
        "drinks_item_3"
      ]
    },
    "drinks_title": {
      "type": "Text",
      "props": {
        "text": "Drinks (Non-Alcoholic):",
        "variant": "h3"
      },
      "children": []
    },
    "drinks_item_1": {
      "type": "Text",
      "props": {
        "text": "Water Bottles: Essential for everyone; purchase in bulk."
      },
      "children": []
    },
    "drinks_item_2": {
      "type": "Text",
      "props": {
        "text": "Large Jugs of Lemonade/Iced Tea: Prepare homemade or buy large store-brand jugs."
      },
      "children": []
    },
    "drinks_item_3": {
      "type": "Text",
      "props": {
        "text": "Juice Boxes/Pouches: A few options for variety, especially if there are younger guests."
      },
      "children": []
    },
    "checklist_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "checklist_header",
        "comfort_seating_stack",
        "food_drink_management_stack",
        "cleanup_safety_stack",
        "activities_extras_stack"
      ]
    },
    "checklist_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "checklist_icon",
        "checklist_title"
      ]
    },
    "checklist_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/list-check.svg"
      },
      "children": []
    },
    "checklist_title": {
      "type": "Text",
      "props": {
        "text": "Essential Picnic Checklist",
        "variant": "h2"
      },
      "children": []
    },
    "comfort_seating_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "comfort_seating_title",
        "comfort_seating_item_1",
        "comfort_seating_item_2",
        "comfort_seating_item_3",
        "comfort_seating_item_4",
        "comfort_seating_item_5"
      ]
    },
    "comfort_seating_title": {
      "type": "Text",
      "props": {
        "text": "Comfort & Seating:",
        "variant": "h3"
      },
      "children": []
    },
    "comfort_seating_item_1": {
      "type": "Text",
      "props": {
        "text": "Large picnic blankets or sheets"
      },
      "children": []
    },
    "comfort_seating_item_2": {
      "type": "Text",
      "props": {
        "text": "Portable folding chairs or cushions (optional)"
      },
      "children": []
    },
    "comfort_seating_item_3": {
      "type": "Text",
      "props": {
        "text": "Sunscreen and hats"
      },
      "children": []
    },
    "comfort_seating_item_4": {
      "type": "Text",
      "props": {
        "text": "Bug spray"
      },
      "children": []
    },
    "comfort_seating_item_5": {
      "type": "Text",
      "props": {
        "text": "Small portable speaker"
      },
      "children": []
    },
    "food_drink_management_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "food_drink_management_title",
        "food_drink_management_item_1",
        "food_drink_management_item_2",
        "food_drink_management_item_3",
        "food_drink_management_item_4",
        "food_drink_management_item_5",
        "food_drink_management_item_6"
      ]
    },
    "food_drink_management_title": {
      "type": "Text",
      "props": {
        "text": "Food & Drink Management:",
        "variant": "h3"
      },
      "children": []
    },
    "food_drink_management_item_1": {
      "type": "Text",
      "props": {
        "text": "Cooler(s) with plenty of ice packs (for food and drinks)"
      },
      "children": []
    },
    "food_drink_management_item_2": {
      "type": "Text",
      "props": {
        "text": "Reusable or disposable plates, cups, and cutlery"
      },
      "children": []
    },
    "food_drink_management_item_3": {
      "type": "Text",
      "props": {
        "text": "Napkins and paper towels"
      },
      "children": []
    },
    "food_drink_management_item_4": {
      "type": "Text",
      "props": {
        "text": "Serving utensils (tongs, spoons)"
      },
      "children": []
    },
    "food_drink_management_item_5": {
      "type": "Text",
      "props": {
        "text": "Bottle opener/corkscrew (if bringing sparkling cider or similar)"
      },
      "children": []
    },
    "food_drink_management_item_6": {
      "type": "Text",
      "props": {
        "text": "Trash bags (for waste and recycling)"
      },
      "children": []
    },
    "cleanup_safety_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "cleanup_safety_title",
        "cleanup_safety_item_1",
        "cleanup_safety_item_2",
        "cleanup_safety_item_3",
        "cleanup_safety_item_4"
      ]
    },
    "cleanup_safety_title": {
      "type": "Text",
      "props": {
        "text": "Cleanup & Safety:",
        "variant": "h3"
      },
      "children": []
    },
    "cleanup_safety_item_1": {
      "type": "Text",
      "props": {
        "text": "Wet wipes/hand sanitizer"
      },
      "children": []
    },
    "cleanup_safety_item_2": {
      "type": "Text",
      "props": {
        "text": "First-aid kit"
      },
      "children": []
    },
    "cleanup_safety_item_3": {
      "type": "Text",
      "props": {
        "text": "Small trash bags for personal waste"
      },
      "children": []
    },
    "cleanup_safety_item_4": {
      "type": "Text",
      "props": {
        "text": "Paper towels"
      },
      "children": []
    },
    "activities_extras_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "activities_extras_title",
        "activities_extras_item_1",
        "activities_extras_item_2",
        "activities_extras_item_3"
      ]
    },
    "activities_extras_title": {
      "type": "Text",
      "props": {
        "text": "Activities & Extras:",
        "variant": "h3"
      },
      "children": []
    },
    "activities_extras_item_1": {
      "type": "Text",
      "props": {
        "text": "Frisbee, ball, or other outdoor games"
      },
      "children": []
    },
    "activities_extras_item_2": {
      "type": "Text",
      "props": {
        "text": "Birthday candles and lighter (if bringing a cake)"
      },
      "children": []
    },
    "activities_extras_item_3": {
      "type": "Text",
      "props": {
        "text": "Small gifts/party favors (optional)"
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_header",
        "share_plan_button",
        "add_to_calendar_button",
        "find_picnic_spots_button"
      ]
    },
    "quick_actions_header": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "share_plan_button": {
      "type": "Button",
      "props": {
        "label": "Share Plan"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/share-picnic-plan"
          }
        }
      }
    },
    "add_to_calendar_button": {
      "type": "Button",
      "props": {
        "label": "Add to Calendar"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/add-to-calendar"
          }
        }
      }
    },
    "find_picnic_spots_button": {
      "type": "Button",
      "props": {
        "label": "Find Central Park Picnic Spots"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/search/central+park+picnic+spots"
          }
        }
      }
    }
  }
}
